// Mnożenie wielomianów przez FFT. Wejście: n m, potem n współczynników A i m współczynników B (od a_0).
// Wyjście: n + m - 1 współczynników C = A * B. Współczynniki całkowite, wynik do ~10^14.
#include <bits/stdc++.h>
using namespace std;
typedef complex<double> cd;
const double PI = acos(-1.0);

void fft(vector<cd> &a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {          // permutacja bit-reverse
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    vector<cd> root(n / 2);                       // pierwiastki z cos/sin wprost — bez kumulacji błędu
    for (int i = 0; i < n / 2; i++) root[i] = polar(1.0, (invert ? -2 : 2) * PI * i / n);
    for (int len = 2; len <= n; len <<= 1) {      // motylki: łączymy bloki długości len/2
        int step = n / len;
        for (int i = 0; i < n; i += len)
            for (int j = 0; j < len / 2; j++) {
                cd u = a[i + j], v = a[i + j + len / 2] * root[j * step];
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
            }
    }
    if (invert) for (cd &x : a) x /= n;
}

vector<long long> multiply(const vector<long long> &a, const vector<long long> &b) {
    if (a.empty() || b.empty()) return {};
    int need = a.size() + b.size() - 1, n = 1;
    while (n < need) n <<= 1;                     // potęga dwójki >= |A| + |B| - 1 (inaczej splot się „zawinie”)
    vector<cd> fa(a.begin(), a.end()), fb(b.begin(), b.end());
    fa.resize(n); fb.resize(n);
    fft(fa, false); fft(fb, false);               // wartości w n pierwiastkach z jedności
    for (int i = 0; i < n; i++) fa[i] *= fb[i];   // iloczyn wielomianów = iloczyn wartości
    fft(fa, true);                                // z powrotem do współczynników
    vector<long long> res(need);
    for (int i = 0; i < need; i++) res[i] = llround(fa[i].real());   // llround, NIE (long long)!
    return res;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<long long> a(n), b(m);
    for (auto &x : a) cin >> x;
    for (auto &x : b) cin >> x;
    vector<long long> c = multiply(a, b);
    for (size_t i = 0; i < c.size(); i++) cout << c[i] << " \n"[i + 1 == c.size()];
}

