// Mnożenie wielomianów modulo 998244353 przez NTT. Wejście: n, m, współczynniki A (n), B (m).
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 998244353, G = 3;   // 998244353 = 119 * 2^23 + 1, pierwiastek pierwotny 3

ll power(ll a, ll e) {
    ll r = 1; a %= MOD;
    for (; e > 0; e >>= 1, a = a * a % MOD)
        if (e & 1) r = r * a % MOD;
    return r;
}

void ntt(vector<ll> &a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {          // permutacja bit-reverse (jak w FFT)
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        ll wlen = power(G, (MOD - 1) / len);      // pierwiastek z jedności stopnia len
        if (invert) wlen = power(wlen, MOD - 2);  // odwrotny dla transformaty odwrotnej
        for (int i = 0; i < n; i += len) {
            ll w = 1;
            for (int j = 0; j < len / 2; j++) {
                ll u = a[i + j], v = a[i + j + len / 2] * w % MOD;
                a[i + j] = u + v < MOD ? u + v : u + v - MOD;
                a[i + j + len / 2] = u - v >= 0 ? u - v : u - v + MOD;
                w = w * wlen % MOD;
            }
        }
    }
    if (invert) {
        ll inv_n = power(n, MOD - 2);
        for (ll &x : a) x = x * inv_n % MOD;
    }
}

vector<ll> multiply(vector<ll> a, vector<ll> b) {
    if (a.empty() || b.empty()) return {};
    int need = a.size() + b.size() - 1, n = 1;
    while (n < need) n <<= 1;
    a.resize(n); b.resize(n);
    ntt(a, false); ntt(b, false);
    for (int i = 0; i < n; i++) a[i] = a[i] * b[i] % MOD;
    ntt(a, true);
    a.resize(need);
    return a;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<ll> a(n), b(m);
    for (auto &x : a) { cin >> x; x %= MOD; if (x < 0) x += MOD; }
    for (auto &x : b) { cin >> x; x %= MOD; if (x < 0) x += MOD; }
    vector<ll> c = multiply(a, b);
    for (size_t i = 0; i < c.size(); i++) cout << c[i] << " \n"[i + 1 == c.size()];
}

// Splot modulo DOWOLNA liczba (np. 10^9+7): trzy NTT na różnych liczbach pierwszych + CRT (Garner).
// Działa, gdy prawdziwy współczynnik < m1*m2*m3 ≈ 7,8·10^25 (np. n ≤ 10^6, wartości < 10^9+7).
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll power(ll a, ll e, ll m) {
    ll r = 1; a %= m;
    for (; e > 0; e >>= 1, a = a * a % m)
        if (e & 1) r = r * a % m;
    return r;
}

template <ll MOD, ll G>
vector<ll> mulMod(vector<ll> a, vector<ll> b) {   // zwykłe NTT dla jednej liczby pierwszej
    int need = a.size() + b.size() - 1, n = 1;
    while (n < need) n <<= 1;
    a.resize(n); b.resize(n);
    auto ntt = [&](vector<ll> &x, bool inv) {
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j & bit; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) swap(x[i], x[j]);
        }
        for (int len = 2; len <= n; len <<= 1) {
            ll wl = power(G, (MOD - 1) / len, MOD);
            if (inv) wl = power(wl, MOD - 2, MOD);
            for (int i = 0; i < n; i += len) {
                ll w = 1;
                for (int j = 0; j < len / 2; j++, w = w * wl % MOD) {
                    ll u = x[i + j], v = x[i + j + len / 2] * w % MOD;
                    x[i + j] = (u + v) % MOD;
                    x[i + j + len / 2] = (u - v + MOD) % MOD;
                }
            }
        }
        if (inv) { ll ni = power(n, MOD - 2, MOD); for (ll &v : x) v = v * ni % MOD; }
    };
    for (ll &v : a) v %= MOD;
    for (ll &v : b) v %= MOD;
    ntt(a, false); ntt(b, false);
    for (int i = 0; i < n; i++) a[i] = a[i] * b[i] % MOD;
    ntt(a, true);
    a.resize(need);
    return a;
}

vector<ll> multiplyAnyMod(const vector<ll> &a, const vector<ll> &b, ll mod) {
    const ll m1 = 998244353, m2 = 167772161, m3 = 469762049;
    auto c1 = mulMod<m1, 3>(a, b), c2 = mulMod<m2, 3>(a, b), c3 = mulMod<m3, 3>(a, b);
    const ll inv_m1_m2 = power(m1, m2 - 2, m2);               // m1^(-1) mod m2
    const ll inv_m12_m3 = power(m1 % m3 * m2 % m3, m3 - 2, m3); // (m1*m2)^(-1) mod m3
    const ll m12_mod = m1 % mod * (m2 % mod) % mod;
    vector<ll> res(c1.size());
    for (size_t i = 0; i < c1.size(); i++) {
        ll x1 = c1[i];                                                   // x = x1 + x2*m1 + x3*m1*m2
        ll x2 = (c2[i] - x1 % m2 + m2) % m2 * inv_m1_m2 % m2;
        ll t = (x1 + x2 * m1) % m3;                                      // x2*m1 < 1,7·10^17 — mieści się
        ll x3 = (c3[i] - t + m3) % m3 * inv_m12_m3 % m3;
        res[i] = (x1 % mod + x2 % mod * (m1 % mod) + x3 % mod * m12_mod) % mod;
    }
    return res;
}

int main() {
    const ll MOD = 1'000'000'007;
    int n, m;
    cin >> n >> m;
    vector<ll> a(n), b(m);
    for (auto &x : a) cin >> x;
    for (auto &x : b) cin >> x;
    auto c = multiplyAnyMod(a, b, MOD);
    for (size_t i = 0; i < c.size(); i++) cout << c[i] << " \n"[i + 1 == c.size()];
}

