// Układ n równań liniowych z m niewiadomymi (double). Wejście: n m, potem n wierszy: a_i1 ... a_im b_i.
// Wynik: NIE (brak rozwiązań), NIESKONCZENIE (wiele) albo wartości x_1..x_m.
#include <bits/stdc++.h>
using namespace std;
const double EPS = 1e-9;

// a: n wierszy po m+1 liczb (ostatnia kolumna = prawa strona). Zwraca 0 / 1 / 2 (= nieskończenie wiele).
int gauss(vector<vector<double>> a, vector<double> &ans) {
    int n = a.size(), m = (int)a[0].size() - 1;
    vector<int> where(m, -1);                 // where[c] = wiersz, w którym zmienna c jest wiodąca
    for (int col = 0, row = 0; col < m && row < n; col++) {
        int sel = row;                        // częściowy wybór elementu głównego: największy |a[i][col]|
        for (int i = row; i < n; i++)
            if (fabs(a[i][col]) > fabs(a[sel][col])) sel = i;
        if (fabs(a[sel][col]) < EPS) continue;   // kolumna zerowa -> zmienna wolna
        swap(a[sel], a[row]);
        where[col] = row;
        for (int i = 0; i < n; i++)
            if (i != row) {                   // zerujemy kolumnę col we WSZYSTKICH innych wierszach (Gauss–Jordan)
                double c = a[i][col] / a[row][col];
                for (int j = col; j <= m; j++) a[i][j] -= a[row][j] * c;
            }
        row++;
    }
    ans.assign(m, 0);
    for (int c = 0; c < m; c++)
        if (where[c] != -1) ans[c] = a[where[c]][m] / a[where[c]][c];
    for (int i = 0; i < n; i++) {             // sprawdzenie: sprzeczny wiersz 0 = b, b ≠ 0
        double s = 0;
        for (int j = 0; j < m; j++) s += ans[j] * a[i][j];
        if (fabs(s - a[i][m]) > EPS) return 0;
    }
    for (int c = 0; c < m; c++)
        if (where[c] == -1) return 2;
    return 1;
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<double>> a(n, vector<double>(m + 1));
    for (auto &row : a)
        for (auto &x : row) cin >> x;
    vector<double> x;
    int r = gauss(a, x);
    if (r == 0) cout << "NIE\n";
    else if (r == 2) cout << "NIESKONCZENIE\n";
    else {
        cout << fixed << setprecision(6);
        for (double v : x) cout << v + 0.0 << "\n";   // + 0.0 usuwa "-0.000000"
    }
}

// Gauss modulo liczba pierwsza p: rozwiązanie układu, wyznacznik i rząd macierzy — dokładnie, bez EPS.
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1'000'000'007;

ll power(ll a, ll e) {
    ll r = 1; a %= MOD;
    for (; e > 0; e >>= 1, a = a * a % MOD)
        if (e & 1) r = r * a % MOD;
    return r;
}
ll inv(ll a) { return power(a, MOD - 2); }   // MOD pierwsze -> Fermat

// a: n wierszy po m+1 (ostatnia kolumna = b), wartości w [0, MOD). Zwraca 0 / 1 / 2 (nieskończenie wiele,
// wtedy w ans jedno z rozwiązań: zmienne wolne = 0). Liczba rozwiązań przy 2 to MOD^(liczba zmiennych wolnych).
int gaussMod(vector<vector<ll>> a, vector<ll> &ans) {
    int n = a.size(), m = (int)a[0].size() - 1;
    vector<int> where(m, -1);
    int row = 0;
    for (int col = 0; col < m && row < n; col++) {
        int sel = -1;
        for (int i = row; i < n; i++) if (a[i][col] != 0) { sel = i; break; }   // dowolny niezerowy
        if (sel == -1) continue;
        swap(a[sel], a[row]);
        ll iv = inv(a[row][col]);
        for (int j = col; j <= m; j++) a[row][j] = a[row][j] * iv % MOD;   // wiodący = 1
        for (int i = 0; i < n; i++)
            if (i != row && a[i][col] != 0) {
                ll c = a[i][col];
                for (int j = col; j <= m; j++) a[i][j] = (a[i][j] - c * a[row][j] % MOD + MOD) % MOD;
            }
        where[col] = row++;
    }
    for (int i = row; i < n; i++)             // wiersz 0 ... 0 | b z b ≠ 0 -> sprzeczność
        if (a[i][m] != 0) return 0;
    ans.assign(m, 0);
    for (int c = 0; c < m; c++)
        if (where[c] != -1) ans[c] = a[where[c]][m];
    return row < m ? 2 : 1;                   // rząd < liczba zmiennych -> są zmienne wolne
}

// Wyznacznik macierzy kwadratowej modulo MOD w O(n^3).
ll detMod(vector<vector<ll>> a) {
    int n = a.size();
    ll det = 1;
    for (int col = 0; col < n; col++) {
        int sel = -1;
        for (int i = col; i < n; i++) if (a[i][col] != 0) { sel = i; break; }
        if (sel == -1) return 0;
        if (sel != col) { swap(a[sel], a[col]); det = (MOD - det) % MOD; }   // zamiana wierszy = zmiana znaku
        det = det * a[col][col] % MOD;
        ll iv = inv(a[col][col]);
        for (int i = col + 1; i < n; i++) {
            ll c = a[i][col] * iv % MOD;
            for (int j = col; j < n; j++) a[i][j] = (a[i][j] - c * a[col][j] % MOD + MOD) % MOD;
        }
    }
    return det;
}

// Rząd macierzy n x m modulo MOD (liczba niezależnych wierszy).
int rankMod(vector<vector<ll>> a) {
    int n = a.size(), m = a[0].size(), row = 0;
    for (int col = 0; col < m && row < n; col++) {
        int sel = -1;
        for (int i = row; i < n; i++) if (a[i][col] != 0) { sel = i; break; }
        if (sel == -1) continue;
        swap(a[sel], a[row]);
        ll iv = inv(a[row][col]);
        for (int i = row + 1; i < n; i++) {
            ll c = a[i][col] * iv % MOD;
            for (int j = col; j < m; j++) a[i][j] = (a[i][j] - c * a[row][j] % MOD + MOD) % MOD;
        }
        row++;
    }
    return row;
}

