const int MAXM = 1000;                              // max liczba zmiennych
// Układ XOR: wiersz i = współczynniki bitowe (bity 0..m-1) i prawa strona w bicie m.
// Zwraca -1 (sprzeczny) albo liczbę zmiennych wolnych (rozwiązań jest 2^wolne); x = jedno rozwiązanie.
int gaussXor(vector<bitset<MAXM + 1>> a, int m, bitset<MAXM> &x) {
    int n = a.size(), row = 0;
    vector<int> where(m, -1);
    for (int col = 0; col < m && row < n; col++) {
        for (int i = row; i < n; i++)
            if (a[i][col]) { swap(a[i], a[row]); break; }
        if (!a[row][col]) continue;
        where[col] = row;
        for (int i = 0; i < n; i++)
            if (i != row && a[i][col]) a[i] ^= a[row];     // cały wiersz naraz: O(m/64)
        row++;
    }
    for (int i = row; i < n; i++) if (a[i][m]) return -1;   // 0 = 1
    x.reset();
    for (int c = 0; c < m; c++) if (where[c] != -1) x[c] = a[where[c]][m];
    return m - row;
}

