// Baza liniowa XOR dla liczb < 2^60. Wejście: n, n liczb, potem q zapytań "x k":
// czy x jest XOR-em podzbioru oraz k-ty najmniejszy możliwy XOR (k od 0; XOR pustego zbioru = 0 to k = 0).
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int B = 60;                              // liczba bitów

struct XorBasis {
    ll b[B] = {};                              // b[i] = wektor bazowy z najstarszym bitem i (albo 0)
    int sz = 0;                                // rząd = liczba wektorów w bazie
    bool insert(ll x) {                        // true, jeśli x był niezależny (powiększył bazę)
        for (int i = B - 1; i >= 0; i--) {
            if (!(x >> i & 1)) continue;
            if (!b[i]) { b[i] = x; sz++; return true; }
            x ^= b[i];                         // kasujemy bit i i redukujemy dalej
        }
        return false;                          // x zredukował się do 0 -> zależny od bazy
    }
    bool canMake(ll x) const {                 // czy x = XOR pewnego podzbioru
        for (int i = B - 1; i >= 0; i--)
            if (x >> i & 1) {
                if (!b[i]) return false;
                x ^= b[i];
            }
        return true;
    }
    ll maxXor(ll start = 0) const {            // max (start ^ XOR podzbioru), zachłannie od najstarszego bitu
        ll r = start;
        for (int i = B - 1; i >= 0; i--) r = max(r, r ^ b[i]);
        return r;
    }
    ll kth(ll k) const {                       // k-ty najmniejszy z 2^sz możliwych XOR-ów (0 <= k < 2^sz)
        ll c[B];
        copy(b, b + B, c);
        for (int i = B - 1; i >= 0; i--)       // postać zredukowana: bit wiodący i tylko w c[i]
            for (int j = i - 1; j >= 0; j--)
                if (c[j] && (c[i] >> j & 1)) c[i] ^= c[j];
        ll r = 0;
        int t = 0;
        for (int i = 0; i < B; i++)
            if (c[i]) { if (k >> t & 1) r ^= c[i]; t++; }   // t-ty bit k <-> t-ty wektor (rosnąco)
        return r;
    }
};

int main() {
    int n, q;
    cin >> n;
    XorBasis xb;
    for (int i = 0; i < n; i++) { ll a; cin >> a; xb.insert(a); }
    cout << "rzad " << xb.sz << ", roznych XOR-ow: " << (1LL << xb.sz) << ", max: " << xb.maxXor() << "\n";
    cin >> q;
    while (q--) {
        ll x, k;
        cin >> x >> k;
        cout << (xb.canMake(x) ? "TAK " : "NIE ");
        if (k < (1LL << xb.sz)) cout << xb.kth(k) << "\n";
        else cout << "-1\n";
    }
}

