// Nieporządki D(n), liczby Stirlinga II rodzaju S(n,k) i liczby Bella B(n) modulo 10^9+7 dla n <= N.
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1'000'000'007;
const int N = 1000;

ll D[N + 1], S[N + 1][N + 1], Bell[N + 1];

int main() {
    D[0] = 1; D[1] = 0;                                   // D(n) = (n-1) * (D(n-1) + D(n-2))
    for (int n = 2; n <= N; n++) D[n] = (n - 1) * ((D[n - 1] + D[n - 2]) % MOD) % MOD;

    S[0][0] = 1;                                          // S(n,k) = k*S(n-1,k) + S(n-1,k-1)
    for (int n = 1; n <= N; n++)
        for (int k = 1; k <= n; k++)
            S[n][k] = (k * S[n - 1][k] + S[n - 1][k - 1]) % MOD;

    for (int n = 0; n <= N; n++) {                        // B(n) = suma S(n,k) po k
        Bell[n] = 0;
        for (int k = 0; k <= n; k++) Bell[n] = (Bell[n] + S[n][k]) % MOD;
    }

    int n, k;
    cin >> n >> k;                                        // 0 <= k <= n <= N
    cout << "D(" << n << ") = " << D[n] << "\n";
    cout << "S(" << n << "," << k << ") = " << S[n][k] << "\n";
    cout << "B(" << n << ") = " << Bell[n] << "\n";
}

// S(n, k) dla dużego n (np. 10^18) i k <= ~10^6: wzór z włączeń-wyłączeń, O(k log n).
// S(n,k) = 1/k! * sum_{j=0..k} (-1)^j * C(k,j) * (k-j)^n
const long long MOD = 1'000'000'007;
long long pw(long long a, long long e) {
    long long r = 1; a %= MOD;
    for (; e > 0; e >>= 1, a = a * a % MOD) if (e & 1) r = r * a % MOD;
    return r;
}
long long stirling2(long long n, int k) {
    vector<long long> f(k + 1, 1), inv(k + 1, 1);
    for (int i = 1; i <= k; i++) f[i] = f[i - 1] * i % MOD;
    inv[k] = pw(f[k], MOD - 2);
    for (int i = k; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
    long long s = 0;
    for (int j = 0; j <= k; j++) {
        long long term = f[k] * inv[j] % MOD * inv[k - j] % MOD * pw(k - j, n) % MOD;   // C(k,j)*(k-j)^n
        s = (j % 2 ? s - term + MOD : s + term) % MOD;
    }
    return s * inv[k] % MOD;                // dzielimy przez k!
}

