// Sito liniowe: liczby pierwsze, mu(n), phi(n), najmniejszy dzielnik pierwszy — wszystko w O(N).
// Potem: liczba par (i, j), 1 <= i <= n, 1 <= j <= m, z NWD(i, j) = 1 w O(sqrt n + sqrt m) na zapytanie.
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 1'000'000;            // 4 tablice int: ~16 MB (dla 10^7 już 160 MB!)

int mu[N + 1], phi[N + 1], lp[N + 1], prefMu[N + 1];
vector<int> primes;

void sieve() {
    mu[1] = 1; phi[1] = 1;
    for (int i = 2; i <= N; i++) {
        if (lp[i] == 0) { lp[i] = i; primes.push_back(i); mu[i] = -1; phi[i] = i - 1; }
        for (int p : primes) {
            if (p > lp[i] || (ll)i * p > N) break;
            lp[i * p] = p;                     // każda liczba złożona zostaje skreślona DOKŁADNIE raz
            if (p == lp[i]) {                  // p dzieli i: p^2 | i*p
                mu[i * p] = 0;
                phi[i * p] = phi[i] * p;
            } else {                           // p nie dzieli i: NWD(i, p) = 1 -> multiplikatywność
                mu[i * p] = -mu[i];
                phi[i * p] = phi[i] * (p - 1);
            }
        }
    }
    for (int i = 1; i <= N; i++) prefMu[i] = prefMu[i - 1] + mu[i];
}

// sum_{d >= 1} mu(d) * floor(n/d) * floor(m/d); bloki, w których floor(n/d) i floor(m/d) są stałe.
ll coprimePairs(ll n, ll m) {
    ll res = 0;
    for (ll d = 1, nd; d <= min(n, m); d = nd + 1) {
        nd = min(n / (n / d), m / (m / d));
        res += (ll)(prefMu[nd] - prefMu[d - 1]) * (n / d) * (m / d);
    }
    return res;
}

int main() {
    sieve();
    int q;
    cin >> q;
    while (q--) {
        ll n, m;
        cin >> n >> m;                         // n, m <= N
        cout << coprimePairs(n, m) << "\n";
    }
}

