// n punktów kratowych: maksymalna odległość Manhattan (obrót o 45°) i suma odległości Manhattan
// po wszystkich parach (osobno po osiach, sortowanie + sumy prefiksowe). Razem O(n log n).
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n;
    cin >> n;
    vector<ll> x(n), y(n);
    for (int i = 0; i < n; i++) cin >> x[i] >> y[i];

    // |dx| + |dy| = max(|du|, |dv|) dla u = x + y, v = x - y
    ll maxU = LLONG_MIN, minU = LLONG_MAX, maxV = LLONG_MIN, minV = LLONG_MAX;
    for (int i = 0; i < n; i++) {
        ll u = x[i] + y[i], v = x[i] - y[i];
        maxU = max(maxU, u); minU = min(minU, u);
        maxV = max(maxV, v); minV = min(minV, v);
    }
    cout << "max Manhattan: " << max(maxU - minU, maxV - minV) << "\n";

    // suma |x_i - x_j| po parach i < j: po posortowaniu x_i wnosi x_i * i - (suma poprzednich)
    auto pairSum = [](vector<ll> c) {
        sort(c.begin(), c.end());
        ll res = 0, pref = 0;
        for (int i = 0; i < (int)c.size(); i++) {
            res += c[i] * i - pref;
            pref += c[i];
        }
        return res;
    };
    cout << "suma Manhattan po parach: " << pairSum(x) + pairSum(y) << "\n";
}

