// Okręgi na double: przecięcie prostej z okręgiem, dwóch okręgów i pole części wspólnej dwóch kół.
#include <bits/stdc++.h>
using namespace std;
typedef long double ld;
const ld PI = acosl(-1.0L), EPS = 1e-12;

struct P {
    ld x, y;
    P operator+(P o) const { return {x + o.x, y + o.y}; }
    P operator-(P o) const { return {x - o.x, y - o.y}; }
    P operator*(ld k) const { return {x * k, y * k}; }
    ld dot(P o) const { return x * o.x + y * o.y; }
    ld norm2() const { return x * x + y * y; }
    P perp() const { return {-y, x}; }          // obrót o 90° w lewo
};

// Prosta przez A i B (A != B) a okrąg (c, r): 0, 1 (styczna) albo 2 punkty.
vector<P> lineCircle(P a, P b, P c, ld r) {
    P d = b - a;
    P h = a + d * ((c - a).dot(d) / d.norm2());   // rzut środka na prostą
    ld dist2 = (c - h).norm2();
    if (dist2 > r * r + EPS) return {};
    ld t = sqrtl(max((ld)0, r * r - dist2)) / sqrtl(d.norm2());
    if (t < EPS) return {h};
    return {h - d * t, h + d * t};
}

// Okręgi (c1, r1) i (c2, r2): 0, 1 albo 2 punkty. Dla identycznych okręgów (nieskończenie wiele) zwraca {}.
vector<P> circleCircle(P c1, ld r1, P c2, ld r2) {
    P v = c2 - c1;
    ld d2 = v.norm2(), d = sqrtl(d2);
    if (d < EPS) return {};                               // współśrodkowe
    if (d > r1 + r2 + EPS || d < fabsl(r1 - r2) - EPS) return {};   // rozłączne / jeden w drugim
    ld a = (r1 * r1 - r2 * r2 + d2) / (2 * d);            // odległość od c1 do cięciwy
    ld h = sqrtl(max((ld)0, r1 * r1 - a * a));            // połowa długości cięciwy
    P m = c1 + v * (a / d);
    if (h < EPS) return {m};                              // styczne
    P off = v.perp() * (h / d);
    return {m + off, m - off};
}

// Pole części wspólnej dwóch kół.
ld intersectionArea(P c1, ld r1, P c2, ld r2) {
    ld d = sqrtl((c2 - c1).norm2());
    if (d >= r1 + r2) return 0;
    if (d <= fabsl(r1 - r2)) { ld r = min(r1, r2); return PI * r * r; }   // mniejsze koło w większym
    ld al = acosl((d * d + r1 * r1 - r2 * r2) / (2 * d * r1));            // połowa kąta środkowego w c1
    ld be = acosl((d * d + r2 * r2 - r1 * r1) / (2 * d * r2));
    return r1 * r1 * (al - sinl(2 * al) / 2) + r2 * r2 * (be - sinl(2 * be) / 2);   // dwa odcinki koła
}

int main() {
    cout << fixed << setprecision(6);
    for (P p : lineCircle({-5, 0}, {5, 0}, {0, 0}, 2)) cout << p.x << " " << p.y << "\n";        // (-2,0) (2,0)
    for (P p : circleCircle({0, 0}, 5, {8, 0}, 5)) cout << p.x << " " << p.y << "\n";           // (4,-3) (4,3)
    cout << intersectionArea({0, 0}, 1, {1, 0}, 1) << "\n";                                     // 1.228370
}

